options.customCss:
/* ==========================================
   PREMIUM AI JIRA ASSISTANT
   Purple / Indigo / Blue Theme
   Updated: User Message Visibility Fix
========================================== */

:root {
  --chat--color--primary: #7c3aed;
  --chat--color--primary-shade-50: #6d28d9;
  --chat--color--primary--shade-100: #5b21b6;

  --chat--color--secondary: #2563eb;
  --chat--color-secondary-shade-50: #1d4ed8;

  --chat--color-white: #ffffff;
  --chat--color-light: #f5f3ff;
  --chat--color-light-shade-50: #e9e5ff;
  --chat--color-light-shade-100: #d8d1fa;
  --chat--color-medium: #c4b5fd;
  --chat--color-dark: #17133d;
  --chat--color-disabled: #cbd5e1;
  --chat--color-typing: #7c3aed;

  --chat--spacing: 1rem;
  --chat--border-radius: 18px;
  --chat--transition-duration: 0.3s;

  --chat--font-family: Inter, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;

  /* Window */
  --chat--window--width: 100%;
  --chat--window--height: 100%;
  --chat--window--bottom: 0;
  --chat--window--right: 0;
  --chat--window--border: none;
  --chat--window--border-radius: 0;

  /* Header */
  --chat--header-height: auto;
  --chat--header--padding: 2rem;
  --chat--header--background: #17133d;
  --chat--header--color: #ffffff;
  --chat--heading--font-size: 2rem;
  --chat--subtitle--font-size: 1rem;
  --chat--subtitle--line-height: 1.7;

  /* Messages */
  --chat--message--font-size: 1rem;
  --chat--message--padding: 1rem 1.25rem;
  --chat--message--border-radius: 18px;
  --chat--message-line-height: 1.65;
  --chat--message--margin-bottom: 1.2rem;

  /* Bot Messages */
  --chat--message--bot--background: rgba(255,255,255,0.92);
  --chat--message--bot--color: #211b50;
  --chat--message--bot--border: 1px solid rgba(139,92,246,0.15);

  /* User Messages - Updated for readability */
  --chat--message--user--background: linear-gradient(
    135deg,
    #ede9fe,
    #dbeafe
  );

  --chat--message--user--color: #211b50;
  --chat--message--user--border: 1px solid rgba(124,58,237,0.15);

  --chat--message--pre--background: #f1edff;
  --chat--messages-list--padding: 2rem;

  /* Input */
  --chat--textarea--height: 58px;
  --chat--textarea--max-height: 12rem;
  --chat--input--font-size: 1rem;
  --chat--input--border: 1px solid #ddd6fe;
  --chat--input--border-radius: 18px;
  --chat--input--padding: 1rem;
  --chat--input--background: #ffffff;
  --chat--input--text-color: #211b50;
  --chat--input--border-active: 1px solid #8b5cf6;

  /* Footer */
  --chat--footer--background: rgba(255,255,255,0.92);
  --chat--footer--color: #211b50;

  /* Buttons */
  --chat--button--padding: 0.85rem 1.4rem;
  --chat--button--border-radius: 14px;
  --chat--button--font-size: 1rem;

  --chat--button--color--primary: #ffffff;
  --chat--button--background--primary: #7c3aed;
  --chat--button--background--primary--hover: #5b21b6;

  /* Toggle */
  --chat--toggle--size: 62px;
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: #7c3aed;
  --chat--toggle--hover--background: #5b21b6;
  --chat--toggle--color: #ffffff;
}

/* ==========================================
   ANIMATED BACKGROUND
========================================== */

.chat-body {
  position: relative;
  overflow: hidden;

  background:
    radial-gradient(
      circle at 10% 15%,
      rgba(139,92,246,0.20),
      transparent 35%
    ),
    radial-gradient(
      circle at 90% 80%,
      rgba(56,189,248,0.16),
      transparent 35%
    ),
    linear-gradient(
      135deg,
      #f5f3ff,
      #eef2ff,
      #ecfeff
    ) !important;

  background-size: 180% 180%;
  animation: backgroundFlow 16s ease infinite;
}

@keyframes backgroundFlow {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }
}

/* ==========================================
   PREMIUM HEADER
========================================== */

.chat-header {
  position: relative;
  overflow: hidden;
  isolation: isolate;

  background: linear-gradient(
    115deg,
    #17133d,
    #312e81,
    #5b21b6,
    #4338ca
  ) !important;

  background-size: 250% 250% !important;
  animation: headerGradient 12s ease infinite;

  padding: 28px 32px !important;
  border: none !important;

  box-shadow: 0 10px 35px rgba(49,46,129,0.22);
}

@keyframes headerGradient {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }
}

.chat-header::before {
  content: "";
  position: absolute;
  z-index: -1;

  width: 280px;
  height: 280px;

  right: 5%;
  top: -180px;

  border-radius: 50%;
  background: rgba(167,139,250,0.28);

  filter: blur(15px);
  animation: floatGlow 7s ease-in-out infinite alternate;
}

.chat-header::after {
  content: "";
  position: absolute;

  top: 0;
  left: -100%;

  width: 45%;
  height: 100%;

  background: linear-gradient(
    90deg,
    transparent,
    rgba(255,255,255,0.15),
    transparent
  );

  animation: headerShine 8s ease-in-out infinite;
  pointer-events: none;
}

@keyframes headerShine {
  0%, 65% {
    left: -100%;
  }

  100% {
    left: 150%;
  }
}

@keyframes floatGlow {
  from {
    transform: translate(0,0) scale(1);
  }

  to {
    transform: translate(-40px,45px) scale(1.25);
  }
}

/* ==========================================
   MESSAGE CARDS
========================================== */

.chat-message {
  max-width: 78%;
  border-radius: 20px !important;

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;

  animation: messageAppear 0.5s cubic-bezier(.2,.8,.2,1) both;
}

.chat-message:hover {
  transform: translateY(-3px);

  box-shadow: 0 12px 30px rgba(76,29,149,0.12);
}

@keyframes messageAppear {
  from {
    opacity: 0;
    transform: translateY(16px) scale(.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ==========================================
   BOT MESSAGE STYLING
========================================== */

.chat-message:has(.chat-message-markdown) {
  backdrop-filter: blur(14px);
}

/* ==========================================
   USER MESSAGE TEXT VISIBILITY FIX
========================================== */

/* User message bubble */
.chat-message-from-user,
.chat-message--user {
  background: linear-gradient(
    135deg,
    #ede9fe,
    #dbeafe
  ) !important;

  color: #211b50 !important;

  border: 1px solid rgba(124,58,237,0.15) !important;
}

/* User message text */
.chat-message-from-user *,
.chat-message--user * {
  color: #211b50 !important;
}

/* User message paragraphs */
.chat-message-from-user p,
.chat-message--user p,
.chat-message-from-user .chat-message-markdown,
.chat-message--user .chat-message-markdown {
  color: #211b50 !important;
}

/* User message links */
.chat-message-from-user a,
.chat-message--user a {
  color: #5b21b6 !important;
  text-decoration: underline;
}

/* ==========================================
   INPUT AREA
========================================== */

.chat-footer {
  background: rgba(255,255,255,0.86) !important;

  backdrop-filter: blur(20px);

  border-top: 1px solid rgba(139,92,246,0.16) !important;

  box-shadow: 0 -8px 30px rgba(49,46,129,0.06);

  padding: 16px 22px !important;
}

/* Input field */
.chat-input textarea {
  color: #211b50 !important;
  background: #ffffff !important;

  border-radius: 18px !important;

  transition: all 0.3s ease;
}

.chat-input textarea:focus {
  outline: none;

  border-color: #8b5cf6 !important;

  box-shadow: 0 0 0 4px rgba(139,92,246,0.13);
}

.chat-input textarea::placeholder {
  color: #81789f !important;
}

/* ==========================================
   SEND BUTTON
========================================== */

.chat-input-send-button {
  border-radius: 15px !important;

  transition: all 0.3s ease !important;
}

.chat-input-send-button:hover {
  transform: scale(1.1) rotate(-5deg);

  filter: drop-shadow(
    0 5px 12px rgba(124,58,237,0.4)
  );
}

.chat-input-send-button:active {
  transform: scale(.94);
}

/* ==========================================
   SCROLLBAR
========================================== */

.chat-body::-webkit-scrollbar {
  width: 8px;
}

.chat-body::-webkit-scrollbar-thumb {
  background: linear-gradient(
    #8b5cf6,
    #4f46e5
  );

  border-radius: 20px;
}

.chat-body::-webkit-scrollbar-track {
  background: transparent;
}

/* ==========================================
   MOBILE RESPONSIVENESS
========================================== */

@media (max-width: 600px) {
  :root {
    --chat--messages-list--padding: 1rem;
  }

  .chat-header {
    padding: 20px 16px !important;
  }

  .chat-message {
    max-width: 94%;
  }

  .chat-footer {
    padding: 12px !important;
  }
}

/* ==========================================
   ACCESSIBILITY
========================================== */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
